import { allPages } from "@/lib/all-pages";
import { z } from "zod";
import { accountLiquidity, availableToSpend, forecastDaily, withInternalFunding, serializeAccountLiquidity, summarizeCashflow } from "./calculations";
import { requireWorkspace } from "@/lib/auth";
import { evaluatePlan, evaluatePlanForWorkspace } from "./model";
import { loadBalanceEvidence, resolveBalances } from "./balances";
import { buildSourceCoverage, loadSourceCoverageMetadata } from "./source-coverage";
import { expenditurePosting, reportExpenditure } from "./expenditure";
import { loadExpenditureRates } from "./expenditure-rates";
import {forecastInput} from "./forecast-schema";
import { loadWealthItems, wealthOverview } from "./wealth";
export {forecastInput} from "./forecast-schema";

type FinanceContext = Awaited<ReturnType<typeof requireWorkspace>>;

const periodInput = z.object({ from: z.iso.date(), to: z.iso.date(), currencyCode: z.string().regex(/^[A-Z]{3}$/), view: z.enum(["original", "base"]).optional(), accountIds: z.array(z.uuid()).max(100).optional() });
const minorAmount = z.string().regex(/^\d{1,18}$/);
const searchInput = z.object({
  query: z.string().trim().min(1).max(100).optional(),
  from: z.iso.date().optional(), to: z.iso.date().optional(),
  minAmountMinor: minorAmount.optional(), maxAmountMinor: minorAmount.optional(),
  limit: z.number().int().min(1).max(50).default(20),
}).strict();
export async function listAccounts(context?: FinanceContext) {
  const { supabase, workspace } = context ?? await requireWorkspace();
  const { data, error } = await supabase.from("accounts").select("id, name, type, currency_code, version")
    .eq("workspace_id", workspace.id).order("name");
  if (error) throw error;
  return data;
}

export async function getBalances(context?: FinanceContext, canReadImports = true, retainSupport = false) {
  const { supabase, workspace } = context ?? await requireWorkspace();
  const [evidence, sourceMetadata] = await Promise.all([loadBalanceEvidence(supabase, workspace.id, new Date().toISOString()), loadSourceCoverageMetadata(supabase, workspace.id, canReadImports)]);
  return resolveBalances(evidence.accounts.filter(account => !account.archived_at), evidence.snapshots, evidence.ledger, evidence.asOf, workspace.timezone, sourceMetadata).map(account => retainSupport ? { ...account,
    calculationEvidence: { snapshots: evidence.snapshots.filter(snapshot => snapshot.account_id === account.id), ledger: evidence.ledger.filter(row => row.account_id === account.id) } } : account);
}

export async function cashflow(input: unknown, context?: FinanceContext, canReadImports = true) {
  const { from, to, currencyCode, view, accountIds } = periodInput.parse(input);
  if (from > to) throw new Error("From date is after to date");
  const { supabase, workspace } = context ?? await requireWorkspace();
  function loadRows() {
    return allPages<{ id: string; parent_transaction_id: string; account_id: string; posted_on: string; version: number; amount_minor: string; currency_code: string; status: string; kind: string; review_reasons: string[] }>((start, end, count) => {
      const query = supabase.from("effective_transactions")
        .select("id, parent_transaction_id, account_id, posted_on, version, amount_minor::text, currency_code, status, kind, review_reasons", count ? { count } : undefined)
        .eq("workspace_id", workspace.id).gte("posted_on", from).lte("posted_on", to);
      return (accountIds ? query.in("account_id", accountIds) : query).order("id").range(start, end);
    });
  }
  const [rows, sourceMetadata, rates] = await Promise.all([loadRows(), loadSourceCoverageMetadata(supabase, workspace.id, canReadImports),
    view === "base" ? loadExpenditureRates(supabase, workspace.id, { from, to, currencyCode }) : []]);
  const sourceCoverage = buildSourceCoverage({ from, to, ...(view ? {} : { currencyCode }), ...(accountIds ? { accountIds } : {}) }, rows, sourceMetadata?.imports, sourceMetadata?.sources);
  if (view) {
    const reporting = reportExpenditure(rows.map(expenditurePosting), rates, { from, to, currencyCode, view, accountIds });
    return { from, to, currencyCode, sourceCoverage, reporting, calculationEvidence: { rows, rates }, conversionCoverage: reporting.conversionCoverage, resultBasis: reporting.resultBasis,
      ...(reporting.totals ?? { unavailable: reporting.limitation ?? "Reporting evidence unavailable" }),
      evidence: { transactionCount: rows.length, includedTransactionCount: reporting.includedTransactionCount, excludedPendingAndTransfers: true,
        excludedReviewRows: reporting.conversionCoverage.excludedClassificationCount, partial: reporting.status === "incomplete", limitation: reporting.limitation } };
  }
  const total = summarizeCashflow(rows.map(row => ({
    amountMinor: BigInt(row.amount_minor), currencyCode: row.currency_code,
    status: row.status as "posted" | "pending", kind: row.kind as "ordinary" | "transfer" | "refund",
    reviewReasons: row.review_reasons,
  })), currencyCode);
  return total ? {
    from, to, currencyCode, sourceCoverage, calculationEvidence: { rows }, incomeMinor: total.incomeMinor.toString(),
    spendingMinor: total.spendingMinor.toString(), netMinor: total.netMinor.toString(),
    evidence: { transactionCount: rows.length, excludedPendingAndTransfers: true,
      includedTransactionCount: rows.filter(row => row.status === "posted" && row.kind !== "transfer" && !row.review_reasons?.length).length,
      excludedReviewRows: total.excludedReviewRows ?? 0, partial: total.partial ?? false,
      ...(total.partial ? { limitation: "Some rows await classification review and are excluded." } : {}) },
  } : { unavailable: "Some transactions require currency conversion", from, to, currencyCode, sourceCoverage, calculationEvidence: { rows } };
}

export async function searchTransactions(input: unknown, context?: FinanceContext) {
  const { query, from, to, minAmountMinor, maxAmountMinor, limit } = searchInput.parse(input);
  const { supabase, workspace } = context ?? await requireWorkspace();
  const filtered = () => {
    let request = supabase.from("transactions")
      .select("id, account_id, category_id, merchant_id, posted_on, description, amount_minor::text, currency_code, status, kind, review_reasons, version")
      .eq("workspace_id", workspace.id);
    if (from) request = request.gte("posted_on", from);
    if (to) request = request.lte("posted_on", to);
    if (minAmountMinor || maxAmountMinor) {
      const low = minAmountMinor ?? "0", high = maxAmountMinor ?? "999999999999999999";
      request = request.or(`and(amount_minor.gte.${low},amount_minor.lte.${high}),and(amount_minor.gte.-${high},amount_minor.lte.-${low})`);
    }
    return request.order("posted_on", { ascending: false });
  };
  const [exact, similar] = await Promise.all([
    (query ? filtered().ilike("description", `%${query.replace(/[%_]/g, "\\$&")}%`) : filtered()).limit(limit),
    query ? supabase.rpc("similar_transaction_ids", { p_workspace_id: workspace.id, p_query: query, ...(from && { p_from: from }), ...(to && { p_to: to }),
      ...(minAmountMinor && { p_min_minor: minAmountMinor }), ...(maxAmountMinor && { p_max_minor: maxAmountMinor }), p_limit: limit }) : null,
  ]);
  if (exact.error) throw exact.error;
  if (similar?.error) throw similar.error;
  const exactIds = new Set((exact.data ?? []).map(row => row.id));
  const similarIds = ((similar?.data ?? []) as { id: string }[]).map(row => row.id).filter(id => !exactIds.has(id));
  const room = limit - exactIds.size;
  const close = room > 0 && similarIds.length ? await filtered().in("id", similarIds).limit(room) : null;
  if (close?.error) throw close.error;
  const data = [...(exact.data ?? []).map(row => ({ ...row, match: "text" as const })), ...(close?.data ?? []).map(row => ({ ...row, match: "similar_name" as const }))];
  const parents = data;
  type EffectiveSearchRow = { id: string; parent_transaction_id: string; amount_minor: string; currency_code: string; status: string; kind: string; review_reasons: string[] };
  const effective: EffectiveSearchRow[] = [];
  if (parents.length) for (let offset = 0; ; offset += 500) {
    const page = await supabase.from("effective_transactions")
      .select("id, parent_transaction_id, account_id, posted_on, amount_minor::text, currency_code, status, kind, review_reasons, category_id, merchant_id, version")
      .eq("workspace_id", workspace.id).in("parent_transaction_id", parents.map(row => row.id)).order("id").range(offset, offset + 499);
    if (page.error) throw page.error;
    if (effective.length + (page.data?.length ?? 0) > 100_000) throw new Error("Search allocation evidence exceeds the current limit");
    effective.push(...(page.data ?? []) as EffectiveSearchRow[]);
    if (!page.data || page.data.length < 500) break;
  }
  return parents.map(row => {
    const components = effective.filter(component => component.parent_transaction_id === row.id);
    const unresolved = Boolean(row.review_reasons?.length || components.some(component => component.review_reasons?.length));
    return { ...row, review_reasons: row.review_reasons ?? [], classificationStatus: unresolved ? "unresolved" : "resolved",
      financialKind: unresolved ? null : row.kind, confirmedSpending: !unresolved && row.status === "posted" && row.kind === "ordinary" && BigInt(row.amount_minor) < 0n,
      amountBasis: "canonical_parent", effectiveRows: components,
      allocationSemantics: "Parent amount; effectiveRows are its split components (do not add both).",
      link: `/money/transactions?transaction=${row.id}` };
  });
}

export async function listWealth(context?: FinanceContext) {
  const { supabase, workspace } = context ?? await requireWorkspace();
  return wealthOverview(await loadWealthItems(supabase, workspace.id));
}

export async function listGoals(context?: FinanceContext) {
  const { supabase, workspace } = context ?? await requireWorkspace();
  const { data, error } = await supabase.from("goals")
    .select("id, name, target_minor::text, currency_code, target_date, status, version")
    .eq("workspace_id", workspace.id).order("created_at", { ascending: false });
  if (error) throw error;
  return data;
}

export async function evaluateForecast(input: unknown, context?: FinanceContext) {
  const args = forecastInput.parse(input);
  const plan = context ? await evaluatePlanForWorkspace(context.supabase, context.workspace, args.horizonDays, args.scenarioId, { canReadImports: context.settings.ai_data_scopes.includes("imports") }) : await evaluatePlan(args.horizonDays, args.scenarioId);
  const assumptions = withInternalFunding(plan.input, (args.funding ?? []).map(funding => ({ ...funding, amountMinor: BigInt(funding.amountMinor) })));
  const forecast = forecastDaily(assumptions), available = availableToSpend(assumptions);
  const calculationEvidence = JSON.parse(JSON.stringify({ source: plan.calculationEvidence, input: assumptions, forecast, available }, (_key, value) => typeof value === "bigint" ? value.toString() : value));
  if (forecast.status === "unavailable" || available.status === "unavailable")
    return { status: "unavailable", sourceCoverage: plan.sourceCoverage, sourceVersion: plan.sourceVersion, calculationEvidence, missingInputs: [...new Set([
      ...(forecast.status === "unavailable" ? forecast.missingInputs : []),
      ...(available.status === "unavailable" ? available.missingInputs : []),
    ])] };
  const last = forecast.days.at(-1)!;
  const liquidity = accountLiquidity(assumptions);
  if (liquidity.status === "unavailable") return { ...liquidity, sourceCoverage: plan.sourceCoverage, sourceVersion: plan.sourceVersion, calculationEvidence };
  const account = args.accountId ? liquidity.accounts.find(account => account.accountId === args.accountId) : undefined;
  if (args.accountId && !account) throw new Error("Unknown account");
  return { status: "available", sourceCoverage: plan.sourceCoverage, resultBasis: plan.resultBasis, currencyCode: assumptions.currencyCode, horizonDays: args.horizonDays,
    period: { from: assumptions.startDate, to: last.date },
    sourceVersion: plan.sourceVersion, calculationEvidence: { ...calculationEvidence, liquidity: serializeAccountLiquidity(liquidity) },
    expectedMinor: last.expectedMinor.toString(), conservativeMinor: last.conservativeMinor.toString(),
    optimisticMinor: last.optimisticMinor.toString(), availableToSpendMinor: account?.spendableMinor.toString() ?? null,
    accountId: account?.accountId ?? null, limitingDate: account?.spendingLimitingDate ?? null,
    aggregateAvailableMinor: available.amountMinor.toString(), aggregateLimitingDate: available.limitingDate,
    aggregateRequiresExplicitFunding: true, liquidity: serializeAccountLiquidity(liquidity), casesAreAssumptionsNotProbabilities: true };
}

export const financeToolSchemas = { periodInput, searchInput };
import type { SupabaseClient } from "@supabase/supabase-js";
import { z } from "zod";
import { requireWorkspace } from "@/lib/auth";
import { allPages } from "@/lib/all-pages";
import { perClient } from "@/lib/per-client";
import { investigate, investigationIdentity, investigationSchema, resolveInvestigation, type InvestigationEntities, type InvestigationRow, type InvestigationSpec } from "./investigation";
import { buildSourceCoverage, loadSourceCoverageMetadata } from "./source-coverage";

type Context = { supabase: SupabaseClient; workspace: { id: string } };
const MAX_ROWS = 100_000;

async function allRows<T>(query: (count?: "exact") => { range(from: number, to: number): PromiseLike<{ data: unknown[] | null; error: unknown; count?: number | null }> }): Promise<T[]> {
  const result = await allPages<T>((from, to, count) => query(count).range(from, to));
  if (result.length > MAX_ROWS) throw new Error("Investigation exceeds 100,000 records; narrow its dates or filters");
  return result;
}
const counted = (count?: "exact") => count ? { count } : undefined;
export async function loadInvestigationEntities(context?: Context): Promise<InvestigationEntities> {
  const { supabase, workspace } = context ?? await requireWorkspace();
  const [accounts, categories, merchants, labels] = await Promise.all([
    ...["accounts", "categories", "merchants"].map(table => allRows<{ id: string; name: string }>(count => supabase.from(table).select(table === "accounts" ? "id, name, version" : "id, name", counted(count)).eq("workspace_id", workspace.id).order("id"))),
    allRows<{ tags: string[]; event_name: string | null }>(count => supabase.from("transactions").select("tags, event_name", counted(count)).eq("workspace_id", workspace.id).order("id")),
  ]) as [{ id: string; name: string }[], { id: string; name: string }[], { id: string; name: string }[], { tags: string[]; event_name: string | null }[]];
  return { accounts, categories, merchants, labels: { tags: [...new Set(labels.flatMap(r => r.tags ?? []))].sort(), events: [...new Set(labels.flatMap(r => r.event_name ? [r.event_name] : []))].sort() } };
}
type LedgerRow = {
  id: string; parent_transaction_id: string; account_id: string; category_id: string | null; merchant_id: string | null;
  posted_on: string; amount_minor: string; currency_code: string; status: InvestigationRow["status"]; kind: InvestigationRow["kind"];
  tags: string[]; event_name: string | null; review_reasons: string[]; version: number; description: string; refund_of_id: string | null;
};
const sourcesFor = perClient((supabase: SupabaseClient, workspaceId: string) =>
  allRows<Source>(count => supabase.from("source_transactions").select("id, import_id, status, review_reasons, normalized_row, fee_evidence, imports(run_version, status, undone_at), transaction_sources(transaction_id)", counted(count)).eq("workspace_id", workspaceId).order("id")));
const ratesFor = perClient((supabase: SupabaseClient, workspaceId: string) =>
  allRows<{ id: string; from_currency: string; to_currency: string; rate_text: string; rate_date: string; source: string }>(count => supabase.from("fx_rates").select("id, from_currency, to_currency, rate_text, rate_date, source", counted(count)).eq("workspace_id", workspaceId).order("id")));
type Source = { id: string; import_id: string; status: string; review_reasons: string[]; normalized_row: unknown; fee_evidence: unknown;
  imports: { run_version: number; status: string; undone_at: string | null } | null; transaction_sources: { transaction_id: string }[] | { transaction_id: string } | null };

async function loadRows(context: Context, spec: InvestigationSpec, includeAll = false, canReadImports = true, withSources = canReadImports) {
  const { supabase, workspace } = context;
  const from = [spec.period.from, spec.comparison?.from].filter((v): v is string => Boolean(v)).sort()[0];
  const to = [spec.period.to, spec.comparison?.to].filter((v): v is string => Boolean(v)).sort().at(-1)!;
  const ledger = (count?: "exact") => {
    const query = supabase.from("effective_transactions")
      .select("id, parent_transaction_id, account_id, category_id, merchant_id, posted_on, amount_minor::text, currency_code, status, kind, tags, event_name, review_reasons, version, description, refund_of_id", counted(count))
      .eq("workspace_id", workspace.id);
    return (includeAll ? query : query.gte("posted_on", from).lte("posted_on", to)).order("id");
  };
  const [effective, sources] = await Promise.all([
    allRows<LedgerRow>(ledger),
    withSources ? sourcesFor(supabase, workspace.id) : [],
  ]);
  const byParent = new Map<string, unknown[]>();
  for (const source of sources) for (const link of Array.isArray(source.transaction_sources) ? source.transaction_sources : source.transaction_sources ? [source.transaction_sources] : []) {
    const values = byParent.get(link.transaction_id) ?? [];
    values.push({ id: source.id, importId: source.import_id, link: `/import/${encodeURIComponent(source.import_id)}/review`, status: source.status, import: source.imports,
      identity: investigationIdentity({ normalized: source.normalized_row, fees: source.fee_evidence, reviewReasons: source.review_reasons }) });
    byParent.set(link.transaction_id, values);
  }
  const rows: InvestigationRow[] = effective.map(r => ({ id: r.id, parentId: r.parent_transaction_id, accountId: r.account_id,
    categoryId: r.category_id, merchantId: r.merchant_id, date: r.posted_on, amountMinor: r.amount_minor, currency: r.currency_code,
    status: r.status, kind: r.kind, tags: r.tags ?? [], event: r.event_name, reviewReasons: r.review_reasons ?? [], version: r.version,
    description: r.description, refundOfId: r.refund_of_id, sourceVersions: byParent.get(r.parent_transaction_id) ?? [] }));
  const refundIds = [...new Set(rows.filter(r => r.kind === "refund" && !r.categoryId && r.refundOfId).map(r => r.refundOfId!))];
  for (let offset = 0; offset < refundIds.length; offset += 100) {
    const original = await supabase.from("transactions").select("id, category_id, version").eq("workspace_id", workspace.id).in("id", refundIds.slice(offset, offset + 100));
    if (original.error) throw original.error;
    for (const row of rows) if (row.kind === "refund" && !row.categoryId && row.refundOfId) {
      const parent = original.data?.find(r => r.id === row.refundOfId);
      if (parent) { row.categoryId = parent.category_id; row.sourceVersions = { sources: row.sourceVersions, refundOriginal: parent }; }
    }
  }
  return rows;
}

export async function loadInvestigationDataset(input: unknown, context?: Context, options: { canReadImports?: boolean; includeAll?: boolean; entities?: Promise<InvestigationEntities>; sourceVersions?: boolean } = {}) {
  const ctx = context ?? await requireWorkspace();
  const entities = await (options.entities ?? loadInvestigationEntities(ctx));
  const spec = resolveInvestigation(input, entities);
  const canReadImports = options.canReadImports ?? true;
  const [rows, metadata, rates] = await Promise.all([loadRows(ctx, spec, options.includeAll ?? false, canReadImports, canReadImports && (options.sourceVersions ?? true)), loadSourceCoverageMetadata(ctx.supabase, ctx.workspace.id, canReadImports),
    spec.currencyPolicy.mode === "base" ? ratesFor(ctx.supabase, ctx.workspace.id) : []]);
  const accountIds = spec.accounts?.include?.flatMap(ref => "id" in ref ? [ref.id] : []);
  const scope = { ...(accountIds?.length ? { accountIds } : {}), ...(spec.currencyPolicy.mode === "original" && spec.currencyPolicy.currencies?.length === 1 ? { currencyCode: spec.currencyPolicy.currencies[0] } : {}) };
  const effective = rows.map(r => ({ account_id: r.accountId, posted_on: r.date, currency_code: r.currency, status: r.status, kind: r.kind, review_reasons: r.reviewReasons }));
  const sourceCoverage = { current: buildSourceCoverage({ ...spec.period, ...scope }, effective, metadata?.imports, metadata?.sources),
    comparison: spec.comparison ? buildSourceCoverage({ ...spec.comparison, ...scope }, effective, metadata?.imports, metadata?.sources) : null,
    attribution: "Period/account source coverage spans all categories; query filters and eligibility are reported separately." };
  return { spec, rows, context: { workspaceId: ctx.workspace.id, capturedAt: new Date().toISOString(), sourceCoverage, entities,
    rates: rates.map(r => ({ id: r.id, fromCurrency: r.from_currency, toCurrency: r.to_currency, rateText: r.rate_text, rateDate: r.rate_date, source: r.source })) },
    sourceRevision: investigationIdentity({ rows, metadata, rates, entities }) };
}
export async function runInvestigation(input: unknown, context?: Context, options: { canReadImports?: boolean; entities?: Promise<InvestigationEntities>; sourceVersions?: boolean } = {}) {
  const data = await loadInvestigationDataset(input, context, options);
  const result = investigate(data.spec, data.rows, data.context);
  return { ...result, sourceRevision: data.sourceRevision,
    link: `/money/investigations?${new URLSearchParams({ query: JSON.stringify({ ...data.spec, page: { size: 25, period: "both" } }) })}` };
}

const minor = z.string().regex(/^-?\d{1,19}$/).refine(v => BigInt(v) >= -(2n ** 63n) && BigInt(v) <= 2n ** 63n - 1n, "Amount exceeds bigint range");
export const investigationScenarioSchema = z.object({ query: investigationSchema, overrides: z.array(z.object({
  id: z.uuid(), amountMinor: minor.optional(), date: z.iso.date().optional(), categoryId: z.uuid().nullable().optional(),
}).strict().refine(o => o.amountMinor !== undefined || o.date !== undefined || o.categoryId !== undefined, "Provide an override")).min(1).max(100) }).strict().refine(v => new Set(v.overrides.map(o => o.id)).size === v.overrides.length, "Duplicate override");

export async function evaluateInvestigationScenario(input: unknown, context?: Context, options: { canReadImports?: boolean } = {}) {
  const args = investigationScenarioSchema.parse(input);
  const ctx = context ?? await requireWorkspace();
  const entities = await loadInvestigationEntities(ctx);
  const spec = resolveInvestigation(args.query, entities);
  const dataset = await loadInvestigationDataset(spec, ctx, { ...options, includeAll: true });
  const rows = dataset.rows;
  for (const override of args.overrides) {
    if (!rows.some(r => r.id === override.id)) throw new Error("Unknown owned effective transaction in scenario");
    if (override.categoryId && !entities.categories.some(c => c.id === override.categoryId)) throw new Error("Unknown owned category in scenario");
  }
  const evidence = dataset.context;
  const hypothetical = rows.map(row => {
    const override = args.overrides.find(o => o.id === row.id);
    return override ? { ...row, ...override } : row;
  });
  return { version: 1, canonicalMutations: false, hypothetical: investigate(spec, hypothetical, evidence), baseline: investigate(spec, rows, evidence),
    overrides: args.overrides, limitation: "Read-only effective-row overrides. No canonical edits, bank balances, recurring assumptions or source records are changed." };
}

export const investigationDetailSchema = z.object({ kind: z.enum(["transaction", "recurring"]), id: z.uuid(),
  offset: z.number().int().min(0).max(MAX_ROWS).default(0), size: z.number().int().min(1).max(100).default(25) }).strict();

export async function investigationDetail(input: unknown, context?: Context, options: { canReadImports?: boolean } = {}) {
  const args = investigationDetailSchema.parse(input);
  const ctx = context ?? await requireWorkspace();
  if (args.kind === "transaction") {
    const result = await ctx.supabase.from("transactions").select("id, account_id, posted_on, description, amount_minor::text, currency_code, status, kind, category_id, merchant_id, tags, event_name, review_reasons, version, transfer_id, refund_of_id")
      .eq("workspace_id", ctx.workspace.id).eq("id", args.id).maybeSingle();
    if (result.error) throw result.error;
    if (!result.data) throw new Error("Unknown owned transaction");
    const spec = investigationSchema.parse({ version: 1, period: { from: result.data.posted_on, to: result.data.posted_on } });
    const all = (await loadRows(ctx, spec, false, options.canReadImports ?? true)).filter(r => r.parentId === args.id);
    return { kind: args.kind, transaction: result.data, link: `/money/transactions?transaction=${args.id}`,
      effectiveRows: all.slice(args.offset, args.offset + args.size), total: all.length, nextOffset: args.offset + args.size < all.length ? args.offset + args.size : null };
  }
  const result = await ctx.supabase.from("recurring_series").select("id, account_id, label, cadence, currency_code, amount_min_minor::text, amount_max_minor::text, occurrences, confidence, status, assumption_id, evidence_invalidated")
    .eq("workspace_id", ctx.workspace.id).eq("id", args.id).maybeSingle();
  if (result.error) throw result.error;
  if (!result.data) throw new Error("Unknown owned recurring series");
  const links = await allRows<{ transaction_id: string }>(count => ctx.supabase.from("recurring_series_transactions").select("transaction_id", counted(count)).eq("workspace_id", ctx.workspace.id).eq("series_id", args.id).order("transaction_id"));
  const ids = links.slice(args.offset, args.offset + args.size).map(l => l.transaction_id);
  const transactions = ids.length ? await ctx.supabase.from("transactions").select("id, posted_on, description, amount_minor::text, currency_code, status, kind, review_reasons, version")
    .eq("workspace_id", ctx.workspace.id).in("id", ids).order("posted_on").order("id") : { data: [], error: null };
  if (transactions.error) throw transactions.error;
  return { kind: args.kind, series: result.data, link: "/money/recurring", total: links.length,
    transactions: transactions.data.map(r => ({ ...r, link: `/money/transactions?transaction=${r.id}` })), nextOffset: args.offset + args.size < links.length ? args.offset + args.size : null };
}
