import { z } from "zod";
import type { SupabaseClient } from "@supabase/supabase-js";
import { INSIGHT_TYPES } from "@/lib/insight-types";

export const AI_DATA_SCOPES = ["accounts", "transactions", "planning", "imports"] as const;
export type AiDataScope = typeof AI_DATA_SCOPES[number];
export const AI_AGENTS = {
  chat: { label: "Chat assistant", model: "gpt-6-luna", claude: "claude-opus-5-5" },
  review: { label: "Financial review", model: "gpt-6-luna", claude: "claude-opus-5-5" },
  agents: { label: "Agent team", model: "gpt-6-luna", claude: "claude-haiku-5-5" },
  imports: { label: "Import mapping", model: "gpt-6-luna", claude: "claude-haiku-5-5" },
  organize: { label: "Organization suggestions", model: "gpt-6-luna", claude: "claude-haiku-5-5" },

export async function loadWorkspaceSettings(supabase: SupabaseClient, workspaceId: string): Promise<WorkspaceSettings> {
  const { data, error } = await supabase.from("workspace_settings").select("*").eq("workspace_id", workspaceId).maybeSingle();
  if (error) throw new Error("Workspace preferences unavailable");
  return readSettings(data);
}

export function requireAiScope(settings: WorkspaceSettings | undefined, ...scopes: AiDataScope[]) {
  for (const scope of scopes) if (!(settings ?? DEFAULT_SETTINGS).ai_data_scopes.includes(scope))
    throw new Error(`AI access to ${scope} is disabled in Settings`);
}
import { createHash } from "node:crypto";
import type { Db } from "@/lib/database";
import type { WorkspaceSettings } from "@/lib/settings";
import { loadFinancialReviewEvidence } from "./review-loader";
import {readEvidenceView} from "./evidence-view";
import {z} from "zod";

const COMPARISON_SCOPES = ["accounts", "transactions"] as const;

type EvidenceViewContext = Parameters<typeof readEvidenceView>[0];
export type ReviewFreshness = { status: "current" | "stale" | "unknown"; reason: string };
const NOT_COMPARABLE: ReviewFreshness = { status: "unknown", reason: "Current evidence could not be compared. Check data access and financial inputs before relying on this historical review." };

function fingerprint(value: unknown): string {
  function normalize(item: unknown): unknown {
    if (Array.isArray(item)) return item.map(normalize);
    if (item && typeof item === "object") return Object.fromEntries(Object.entries(item)
      .filter(([key]) => !["evaluatedAt", "evaluated_at", "capturedAt", "verification", "calculationEvidence"].includes(key))
      .sort(([a], [b]) => a.localeCompare(b)).map(([key, child]) => [key, normalize(child)]));
    return item;
  }
  return createHash("sha256").update(JSON.stringify(normalize(value))).digest("hex");
}

export function compareReviewEvidence(saved: unknown, current: unknown): ReviewFreshness {
  if (!saved || typeof saved !== "object") return { status: "unknown", reason: "This historical review has no comparable saved evidence." };
  return fingerprint(saved) === fingerprint(current)
    ? { status: "current", reason: "Saved evidence matches the current financial evidence and review period." }
    : { status: "stale", reason: "Financial evidence, permissions or the review period have changed. Run a new review for current findings." };
}

export async function reviewFreshness(db: Db, workspace: { id: string; display_currency: string; timezone: string }, saved: unknown, settings: WorkspaceSettings, now: Date): Promise<ReviewFreshness> {
  try {
