import Link from "next/link";
import { notFound, redirect } from "next/navigation";
import { requireWorkspace } from "@/lib/auth";
import { reviewFreshness } from "@/lib/finance/review-freshness";
import { ReviewVerification } from "@/components/review-verification";
import { AiMessage } from "@/components/ai-message";
import { AutoRefresh } from "@/components/auto-refresh";

export const metadata = { title: "Saved review" };

function truncate(value: string | null | undefined, max = 280) {
  if (!value) return "";
        .eq("workspace_id", workspace.id)
        .eq("job_id", id)
        .maybeSingle()
    : { data: null, error: null };
  const evidence = analysis?.evidence as { period?: { from?: string; to?: string } } | null;
  const freshness = analysis ? await reviewFreshness(supabase, workspace, analysis.evidence, settings, new Date()) : null;
  const when = (iso: string) => new Date(iso).toLocaleString(workspace.locale, { timeZone: workspace.timezone });
}
const EVIDENCE_RETURN = /^\/ai\/activity\/[0-9a-f-]{36}$/i;
export default async function Page({ params, searchParams }: { params: Promise<{ id: string }>; searchParams: Promise<{ metric?: string; sourcePage?: string; metricPage?: string; q?: string; from?: string }> }) {
  let context: Awaited<ReturnType<typeof requireWorkspace>>;
  try { context = await requireWorkspace(); } catch { redirect("/setup"); }
  const { id } = await params, query = await searchParams;
  const parsed = z.object({ id: z.uuid(), metric: z.string().min(1).max(200).optional(), sourcePage: z.coerce.number().int().min(0).max(1000).default(0), metricPage: z.coerce.number().int().min(0).max(40).default(0), q: z.string().trim().max(100).optional(), from: z.string().regex(EVIDENCE_RETURN).optional().catch(undefined) }).safeParse({ id, ...query });
  if (!parsed.success) notFound();
  const { locale, timezone } = context.workspace;
  const back = parsed.data.from ? { href: parsed.data.from, label: "← Back to the review" } : { href: "/ai/activity?filter=analyses", label: "← AI review history" };
  const failed = await readEvidenceView(context, id, parsed.data.metric).then(view => ({ view, failure: null }), (cause: unknown) => {
    const message = cause instanceof Error ? cause.message : "";
    return { view: null, failure: /mismatch|Metric unavailable/.test(message) ? null : /^AI access to /.test(message) ? "scope" as const : "service" as const };
import { z } from "zod";
import { requireWorkspace } from "@/lib/auth";
import { readEvidenceView } from "@/lib/finance/evidence-view";
export async function GET(request: Request, { params }: { params: Promise<{ id: string }> }) {
  let context: Awaited<ReturnType<typeof requireWorkspace>>;
  try { context = await requireWorkspace(); } catch { return Response.json({ error: "Unauthorized" }, { status: 401 }); }
  const { id } = await params;
  const query = new URL(request.url).searchParams;
  const parsed = z.object({ id: z.uuid(), metric: z.string().min(1).max(200).optional(), source: z.string().min(1).max(200).optional() }).safeParse({ id, metric: query.get("metric") ?? undefined, source: query.get("source") ?? undefined });
  if (!parsed.success) return Response.json({ error: "Invalid evidence request" }, { status: 400 });
  try {
    const view = await readEvidenceView(context, id, parsed.data.metric);
    if (!view) return Response.json({ error: "Evidence unavailable" }, { status: 404 });
    if (parsed.data.source) {
      const source = view.supportingRecords.find(record => record.id === parsed.data.source);
      return source ? Response.json({ source, freshness: view.freshness }, { headers: { "Cache-Control": "private, no-store" } }) : Response.json({ error: "Source unavailable" }, { status: 404 });
    }
    return Response.json(view, { headers: { "Cache-Control": "private, no-store" } });
  } catch (error) {
    return Response.json({ error: "Evidence unavailable" }, { status: error instanceof Error && /unavailable|disabled|ownership/i.test(error.message) ? 404 : 500 });
import { requireWorkspace } from "@/lib/auth";
import { reviewFreshness } from "@/lib/finance/review-freshness";

type Context = { params: Promise<{ id: string }> };

export async function GET(_request: Request, { params }: Context) {
  let context: Awaited<ReturnType<typeof requireWorkspace>>;
  try { context = await requireWorkspace(); }
  catch { return Response.json({ error: "Unauthorized" }, { status: 401 }); }
  const { id } = await params;
  const job = await context.supabase.from("background_jobs").select("id, status, stage, cancel_requested, error, created_at, updated_at, review_request, review_progress")
    .eq("id", id).eq("workspace_id", context.workspace.id).eq("kind", "financial_review").maybeSingle();
  if (job.error) return Response.json({ error: job.error.message }, { status: 500 });
  if (!job.data) return Response.json({ error: "Review not found" }, { status: 404 });
  const analysis = job.data.status === "completed" ? await context.supabase.from("saved_analyses")
    .select("id, title, body, evidence, created_at").eq("job_id", id).eq("workspace_id", context.workspace.id).maybeSingle() : null;
  if (analysis?.error) return Response.json({ error: analysis.error.message }, { status: 500 });
  const saved = analysis?.data;
  const freshness = saved ? await reviewFreshness(context.supabase, context.workspace, saved.evidence, context.settings, new Date()) : null;
  return Response.json({ ...job.data, analysis: saved ? { ...saved, freshness } : null });
}

